#include <stdio.h>

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;
    char S[1005];
    for (int i = 0; i < N; i++) {
        int d;
        scanf("%d", &d);
        S[i] = '0' + d;
    }
    S[N] = '\0';

    for (int L = 1; L <= N; L++) {
        char cur[1005];
        for (int i = 0; i < L; i++) {
            cur[i] = S[i];
        }
        int cur_len = L;
        int pos = 0;
        int success = 0;
        while (pos < N) {
            if (pos + cur_len > N) break;
            int match = 1;
            for (int i = 0; i < cur_len; i++) {
                if (cur[i] != S[pos + i]) {
                    match = 0;
                    break;
                }
            }
            if (!match) break;
            pos += cur_len;
            if (pos == N) {
                success = 1;
                break;
            }
            // increment cur
            int i = cur_len - 1;
            while (i >= 0 && cur[i] == '9') {
                cur[i] = '0';
                i--;
            }
            if (i < 0) {
                // all 9s
                for (int j = cur_len; j > 0; j--) {
                    cur[j] = cur[j-1];
                }
                cur[0] = '1';
                cur_len++;
            } else {
                cur[i]++;
            }
        }
        if (success) {
            for (int i = 0; i < L; i++) {
                putchar(S[i]);
            }
            putchar('\n');
            return 0;
        }
    }
    return 0;
}
